import { Hono } from 'hono'
import { sValidator } from '@hono/standard-validator'
import { Schema, SchemaTransformation } from 'effect'

export const v1Handler = new Hono()
  .get(
    '/v1/account',
    sValidator(
      'query',
      Schema.toStandardSchemaV1(
        Schema.Struct({
          expand: Schema.optionalKey(
            Schema.Unknown.pipe(
              Schema.decodeTo(
                Schema.Unknown,
                SchemaTransformation.transform<unknown, unknown>({
                  decode: (input) =>
                    input === undefined || Array.isArray(input) ? input : [input],
                  encode: (output) => output,
                }),
              ),
              Schema.decodeTo(
                Schema.Array(
                  Schema.String.check(
                    Schema.makeFilter((input) => [...input].length <= 5000, {
                      expected: 'a string of at most 5000 characters',
                    }),
                  ),
                ),
              ),
            ),
          ),
        }),
      ),
    ),
    sValidator(
      'form',
      Schema.toStandardSchemaV1(
        Schema.StructWithRest(Schema.Struct({}), [
          Schema.Record(Schema.String, Schema.Unknown),
        ]).check(Schema.makeFilter((input) => Object.keys(input).length === 0)),
      ),
    ),
    (c) => { throw new Error('Not implemented') },
  )
  .post(
    '/v1/account_links',
    sValidator(
      'form',
      Schema.toStandardSchemaV1(
        Schema.StructWithRest(
          Schema.Struct({
            account: Schema.String.check(
              Schema.makeFilter((input) => [...input].length <= 5000, {
                expected: 'a string of at most 5000 characters',
              }),
            ).annotate({
              description: 'The identifier of the account to create an account link for.',
            }),
            collect: Schema.optionalKey(
              Schema.Literals(['currently_due', 'eventually_due']).annotate({
                description:
                  'The collect parameter is deprecated. Use `collection_options` instead.',
              }),
            ),
            collection_options: Schema.optionalKey(
              Schema.Struct({
                fields: Schema.optionalKey(Schema.Literals(['currently_due', 'eventually_due'])),
                future_requirements: Schema.optionalKey(Schema.Literals(['include', 'omit'])),
              }).annotate({
                description:
                  'Specifies the requirements that Stripe collects from connected accounts in the Connect Onboarding flow.',
              }),
            ),
            expand: Schema.optionalKey(
              Schema.Unknown.pipe(
                Schema.decodeTo(
                  Schema.Unknown,
                  SchemaTransformation.transform<unknown, unknown>({
                    decode: (input) =>
                      input === undefined || Array.isArray(input) ? input : [input],
                    encode: (output) => output,
                  }),
                ),
                Schema.decodeTo(
                  Schema.Array(
                    Schema.String.check(
                      Schema.makeFilter((input) => [...input].length <= 5000, {
                        expected: 'a string of at most 5000 characters',
                      }),
                    ),
                  ),
                ),
              ).annotate({
                description: 'Specifies which fields in the response should be expanded.',
              }),
            ),
            refresh_url: Schema.optionalKey(
              Schema.String.annotate({
                description:
                  "The URL the user will be redirected to if the account link is expired, has been previously-visited, or is otherwise invalid. The URL you specify should attempt to generate a new account link with the same parameters used to create the original account link, then redirect the user to the new account link's URL so they can continue with Connect Onboarding. If a new account link cannot be generated or the redirect fails you should display a useful error to the user.",
              }),
            ),
            return_url: Schema.optionalKey(
              Schema.String.annotate({
                description:
                  'The URL that the user will be redirected to upon leaving or completing the linked flow.',
              }),
            ),
            type: Schema.Literals(['account_onboarding', 'account_update']).annotate({
              description:
                "The type of account link the user is requesting.\n\nYou can create Account Links of type `account_update` only for connected accounts where your platform is responsible for collecting requirements, including Custom accounts. You can't create them for accounts that have access to a Stripe-hosted Dashboard. If you use [Connect embedded components](/connect/get-started-connect-embedded-components), you can include components that allow your connected accounts to update their own information. For an account without Stripe-hosted Dashboard access where Stripe is liable for negative balances, you must use embedded components.",
            }),
          }),
          [Schema.Record(Schema.String, Schema.Unknown)],
        ).check(
          Schema.makeFilter((input) =>
            Object.keys(input).every((key) =>
              [
                'account',
                'collect',
                'collection_options',
                'expand',
                'refresh_url',
                'return_url',
                'type',
              ].includes(key),
            ),
          ),
        ),
      ),
    ),
    (c) => { throw new Error('Not implemented') },
  )
